import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.DSoq407f.js";const f=JSON.parse('{"title":"管理后台总览","description":"","frontmatter":{},"headers":[],"relativePath":"admin/overview.md","filePath":"admin/overview.md","lastUpdated":1786505997000}'),i={name:"admin/overview.md"};function l(o,t,s,n,h,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="管理后台总览" tabindex="-1">管理后台总览 <a class="header-anchor" href="#管理后台总览" aria-label="Permalink to &quot;管理后台总览&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：管理后台能做什么、各功能模块概览。</p></blockquote><p>管理后台是<strong>平台运营方</strong>使用的管理界面，登录入口在 <code>/admin/login</code>。用安装时创建的超级管理员账户登录。</p><h2 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>作用</th></tr></thead><tbody><tr><td><a href="#数据看板">数据看板</a></td><td>平台运营数据总览</td></tr><tr><td><a href="./users">用户管理</a></td><td>管理租户用户、余额、角色</td></tr><tr><td><a href="./adapters">适配器集群</a></td><td>平台适配器与运行节点</td></tr><tr><td><a href="./marketplace">插件市场审核</a></td><td>审核开发者上传的插件</td></tr><tr><td><a href="./subscriptions">订阅与计费</a></td><td>套餐、卡密、订阅用户</td></tr><tr><td><a href="./developers">开发者管理</a></td><td>开发者审批、提现</td></tr><tr><td><a href="./content">内容与公告</a></td><td>公告、弹窗通知</td></tr><tr><td><a href="./settings">系统设置</a></td><td>站点、邮件、支付、注册等</td></tr><tr><td><a href="./audit">审计与日志</a></td><td>操作审计、运行日志</td></tr></tbody></table><h2 id="数据看板" tabindex="-1">数据看板 <a class="header-anchor" href="#数据看板" aria-label="Permalink to &quot;数据看板&quot;">​</a></h2><p>后台首页是数据看板，展示平台关键运营指标：</p><ul><li>用户数、活跃用户</li><li>机器人数量、运行状态</li><li>订阅收入、余额流水</li><li>插件市场销量</li><li>适配器 / 插件运行时状态</li></ul><p>用于快速掌握平台整体运营情况。</p><h2 id="权限说明" tabindex="-1">权限说明 <a class="header-anchor" href="#权限说明" aria-label="Permalink to &quot;权限说明&quot;">​</a></h2><ul><li><strong>超级管理员</strong>：拥有所有权限。</li><li><strong>普通管理员</strong>：按 <a href="./../guide/features#rbac-权限与审计">RBAC</a> 分配的权限，只能操作授权范围内的模块。</li><li>所有管理操作都会记录到<a href="./audit">审计日志</a>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>管理用户 → <a href="./users">用户管理</a></li><li>配置计费 → <a href="./subscriptions">订阅与计费</a></li><li>审核插件 → <a href="./marketplace">插件市场审核</a></li></ul>',13)])])}const p=a(i,[["render",l]]);export{f as __pageData,p as default};
